  "{n} user account(s) restored with their existing passwords": { one: "{n} compte utilisateur restauré avec son mot de passe existant", other: "{n} comptes utilisateurs restaurés avec leurs mots de passe existants" },
  "{n} left alone — username already in use: {names}": { one: "{n} laissé tel quel — nom d'utilisateur déjà utilisé : {names}", other: "{n} laissés tels quels — noms d'utilisateur déjà utilisés : {names}" },
